children:
#kbc-strategic-credit-page-v3{
  --kbc-site-header-height:82px;
  --kbc-admin-bar-height:0px;
  --kbc-total-sticky-offset:calc(var(--kbc-site-header-height) + var(--kbc-admin-bar-height));
  --kbc-page-nav-height:58px;
  --kbc-floating-bar-height:82px;

  --kbc-dark:#201432;
  --kbc-deep:#2b1b43;
  --kbc-medium:#3d285d;
  --kbc-muted-purple:#573a7d;
  --kbc-purple:#5c259c;
  --kbc-bright-purple:#7540dc;
  --kbc-light-purple:#f1eafa;
  --kbc-section-bg:#f7f5fa;
  --kbc-gold:#e5bd59;
  --kbc-gold-hover:#edca72;
  --kbc-text:#292f3d;
  --kbc-muted:#626a7a;
  --kbc-white:#fff;
  --kbc-border:rgba(87,58,125,.14);
  --kbc-dark-border:rgba(255,255,255,.13);
  --kbc-shadow:0 10px 30px rgba(32,20,50,.06);
  --kbc-shadow-raised:0 22px 55px rgba(32,20,50,.14);
  --kbc-radius:18px;
  --kbc-container:1220px;

  /* ======================================================
     EXTERNAL IMAGE LINK 1 — REPLACE ONLY THE URL BELOW
     Recommended size: 1600 x 900 px or larger
  ====================================================== */
  --kbc-story-image:url("https://kentbusinesscollege.com/wp-content/uploads/2026/04/5-3.jpg");

  width:100%;
  margin:0;
  padding:0 0 calc(var(--kbc-floating-bar-height) + 24px);
  overflow-x:clip;
  overflow-y:visible;
  color:var(--kbc-text);
  background:var(--kbc-white);
  font-family:Inter,Arial,Helvetica,sans-serif;
  font-size:16px;
  line-height:1.65;
  -webkit-font-smoothing:antialiased;
  text-rendering:optimizeLegibility;
}
#kbc-strategic-credit-page-v3,
#kbc-strategic-credit-page-v3 *,
#kbc-strategic-credit-page-v3 *::before,
#kbc-strategic-credit-page-v3 *::after{box-sizing:border-box}
#kbc-strategic-credit-page-v3 h1,
#kbc-strategic-credit-page-v3 h2,
#kbc-strategic-credit-page-v3 h3,
#kbc-strategic-credit-page-v3 h4,
#kbc-strategic-credit-page-v3 p,
#kbc-strategic-credit-page-v3 ul,
#kbc-strategic-credit-page-v3 figure{margin-top:0}
#kbc-strategic-credit-page-v3 h1,
#kbc-strategic-credit-page-v3 h2{font-weight:800}
#kbc-strategic-credit-page-v3 h3,
#kbc-strategic-credit-page-v3 h4{font-weight:700}
#kbc-strategic-credit-page-v3 h2{
  margin-bottom:16px;
  color:var(--kbc-dark);
  font-size:clamp(1.85rem,3.4vw,2.8rem);
  line-height:1.08;
  letter-spacing:-.045em;
}
#kbc-strategic-credit-page-v3 h3{
  margin-bottom:10px;
  color:var(--kbc-dark);
  font-size:1.12rem;
  line-height:1.3;
}
#kbc-strategic-credit-page-v3 p{
  margin-bottom:16px;
  color:var(--kbc-muted);
  font-size:15px;
  line-height:1.68;
}
#kbc-strategic-credit-page-v3 a{color:inherit}
#kbc-strategic-credit-page-v3 button{font:inherit}
#kbc-strategic-credit-page-v3 :focus-visible{
  outline:3px solid var(--kbc-gold);
  outline-offset:4px;
}
#kbc-strategic-credit-page-v3 .kbc-container{
  width:min(var(--kbc-container),calc(100% - 40px));
  margin-inline:auto;
}
#kbc-strategic-credit-page-v3 .kbc-section,
#kbc-strategic-credit-page-v3 section[id]{
  position:relative;
  padding:82px 0;
  scroll-margin-top:calc(var(--kbc-total-sticky-offset) + var(--kbc-page-nav-height) + 20px);
}
#kbc-strategic-credit-page-v3 .kbc-section--white{background:var(--kbc-white)}
#kbc-strategic-credit-page-v3 .kbc-section--soft{background:var(--kbc-section-bg)}
#kbc-strategic-credit-page-v3 .kbc-section-heading{
  max-width:810px;
  margin-bottom:40px;
}
#kbc-strategic-credit-page-v3 .kbc-eyebrow{
  display:inline-flex;
  align-items:center;
  gap:10px;
  margin-bottom:14px;
  color:var(--kbc-purple);
  font-size:11px;
  font-weight:800;
  letter-spacing:.14em;
  text-transform:uppercase;
}
#kbc-strategic-credit-page-v3 .kbc-eyebrow::before{
  width:40px;
  height:7px;
  flex:0 0 auto;
  border-radius:999px;
  background:linear-gradient(90deg,var(--kbc-gold),var(--kbc-bright-purple));
  content:"";
}
#kbc-strategic-credit-page-v3 .kbc-lead{
  max-width:790px;
  color:var(--kbc-muted);
  font-size:clamp(1rem,1.7vw,1.17rem);
  line-height:1.72;
}
#kbc-strategic-credit-page-v3 .kbc-grid{display:grid;gap:24px}
#kbc-strategic-credit-page-v3 .kbc-grid--2{grid-template-columns:repeat(2,minmax(0,1fr))}
#kbc-strategic-credit-page-v3 .kbc-grid--3{grid-template-columns:repeat(3,minmax(0,1fr))}
#kbc-strategic-credit-page-v3 .kbc-card{
  position:relative;
  display:flex;
  min-width:0;
  height:100%;
  flex-direction:column;
  padding:25px;
  border:1px solid var(--kbc-border);
  border-radius:var(--kbc-radius);
  background:var(--kbc-white);
  box-shadow:var(--kbc-shadow);
}
#kbc-strategic-credit-page-v3 .kbc-card p:last-child{margin-bottom:0}
#kbc-strategic-credit-page-v3 .kbc-card--light{background:var(--kbc-light-purple)}
#kbc-strategic-credit-page-v3 .kbc-card--dark{
  color:var(--kbc-white);
  border-color:var(--kbc-dark-border);
  background:
    radial-gradient(circle at 100% 0%,rgba(117,64,220,.58),transparent 45%),
    linear-gradient(145deg,var(--kbc-dark),var(--kbc-medium));
}
#kbc-strategic-credit-page-v3 .kbc-card--dark h2,
#kbc-strategic-credit-page-v3 .kbc-card--dark h3,
#kbc-strategic-credit-page-v3 .kbc-card--dark p,
#kbc-strategic-credit-page-v3 .kbc-card--dark li{color:var(--kbc-white)}
#kbc-strategic-credit-page-v3 .kbc-list{
  display:grid;
  gap:11px;
  margin:0;
  padding:0;
  list-style:none;
}
#kbc-strategic-credit-page-v3 .kbc-list li{
  position:relative;
  padding-left:27px;
  color:var(--kbc-muted);
  font-size:14px;
  line-height:1.56;
}
#kbc-strategic-credit-page-v3 .kbc-list li::before{
  position:absolute;
  top:.5em;
  left:0;
  width:12px;
  height:12px;
  border:3px solid var(--kbc-light-purple);
  border-radius:50%;
  background:var(--kbc-purple);
  content:"";
}
#kbc-strategic-credit-page-v3 .kbc-dark-surface .kbc-list li::before,
#kbc-strategic-credit-page-v3 .kbc-card--dark .kbc-list li::before{
  border-color:rgba(255,255,255,.18);
  background:var(--kbc-gold);
}
#kbc-strategic-credit-page-v3 .kbc-note{
  padding:21px 23px;
  border:1px solid var(--kbc-border);
  border-left:4px solid var(--kbc-purple);
  border-radius:0 16px 16px 0;
  background:var(--kbc-white);
  box-shadow:var(--kbc-shadow);
}
#kbc-strategic-credit-page-v3 .kbc-note p{margin-bottom:0}
#kbc-strategic-credit-page-v3 .kbc-note strong{color:var(--kbc-purple)}

#kbc-strategic-credit-page-v3 .kbc-button-row,
#kbc-strategic-credit-page-v3 .kbc-credit-actions{
  display:flex;
  flex-wrap:wrap;
  gap:12px;
  margin-top:28px;
}
#kbc-strategic-credit-page-v3 .kbc-button{
  display:inline-flex;
  min-height:50px;
  align-items:center;
  justify-content:center;
  padding:12px 23px;
  border:1px solid transparent;
  border-radius:11px;
  cursor:pointer;
  text-align:center;
  text-decoration:none;
  font-size:14px;
  font-weight:800;
  line-height:1.2;
  transition:transform .18s ease,background-color .18s ease,border-color .18s ease,box-shadow .18s ease;
}
#kbc-strategic-credit-page-v3 .kbc-button--primary{
  color:#2d230d;
  background:var(--kbc-gold);
  box-shadow:0 10px 24px rgba(229,189,89,.18);
}
#kbc-strategic-credit-page-v3 .kbc-button--primary:hover,
#kbc-strategic-credit-page-v3 .kbc-button--primary:focus-visible{
  transform:translateY(-2px);
  background:var(--kbc-gold-hover);
  box-shadow:0 0 0 4px rgba(229,189,89,.12),0 12px 28px rgba(229,189,89,.35);
}
#kbc-strategic-credit-page-v3 .kbc-button--secondary{
  color:var(--kbc-purple);
  border-color:rgba(92,37,156,.22);
  background:var(--kbc-white);
}
#kbc-strategic-credit-page-v3 .kbc-button--secondary:hover,
#kbc-strategic-credit-page-v3 .kbc-button--secondary:focus-visible{
  transform:translateY(-2px);
  border-color:rgba(92,37,156,.4);
  background:var(--kbc-light-purple);
  box-shadow:0 0 0 4px rgba(92,37,156,.08),0 10px 24px rgba(92,37,156,.18);
}
#kbc-strategic-credit-page-v3 .kbc-button--dark-secondary{
  color:var(--kbc-white);
  border-color:rgba(255,255,255,.24);
  background:rgba(255,255,255,.06);
}
#kbc-strategic-credit-page-v3 .kbc-button--dark-secondary:hover{
  transform:translateY(-2px);
  border-color:rgba(229,189,89,.52);
  background:rgba(229,189,89,.1);
}

#kbc-strategic-credit-page-v3 .kbc-hero{
  position:relative;
  isolation:isolate;
  overflow:hidden;
  color:var(--kbc-white);
  background:
    radial-gradient(circle at 82% 16%,rgba(117,64,220,.4),transparent 30%),
    radial-gradient(circle at 14% 86%,rgba(92,37,156,.28),transparent 30%),
    linear-gradient(135deg,#1b102d,#302048 57%,#201432);
}
#kbc-strategic-credit-page-v3 .kbc-hero::before{
  position:absolute;
  z-index:-1;
  inset:0 0 0 auto;
  width:48%;
  opacity:.17;
  background-image:repeating-linear-gradient(-24deg,transparent 0,transparent 16px,rgba(229,189,89,.45) 17px,transparent 18px);
  content:"";
  mask-image:linear-gradient(to left,#000,transparent);
}
#kbc-strategic-credit-page-v3 .kbc-hero-grid{
  display:grid;
  min-height:670px;
  grid-template-columns:minmax(0,1.08fr) minmax(400px,.92fr);
  gap:58px;
  align-items:center;
  padding:88px 0 78px;
}
#kbc-strategic-credit-page-v3 .kbc-hero-label{
  display:inline-flex;
  min-height:34px;
  align-items:center;
  gap:9px;
  margin-bottom:22px;
  padding:7px 13px;
  border:1px solid rgba(229,189,89,.36);
  border-radius:999px;
  color:var(--kbc-gold);
  background:rgba(229,189,89,.07);
  font-size:10px;
  font-weight:800;
  letter-spacing:.13em;
  text-transform:uppercase;
}
#kbc-strategic-credit-page-v3 .kbc-hero-label::before{
  width:7px;height:7px;border-radius:50%;background:var(--kbc-gold);content:"";
}
#kbc-strategic-credit-page-v3 .kbc-hero h1{
  max-width:750px;
  margin-bottom:24px;
  color:var(--kbc-white);
  font-size:clamp(2.9rem,5.8vw,5rem);
  line-height:.98;
  letter-spacing:-.055em;
}
#kbc-strategic-credit-page-v3 .kbc-hero h1 span{
  display:block;
  margin-top:9px;
  color:var(--kbc-gold);
}
#kbc-strategic-credit-page-v3 .kbc-hero-description{
  max-width:700px;
  margin-bottom:0;
  color:rgba(255,255,255,.78);
  font-size:clamp(1rem,1.8vw,1.17rem);
  line-height:1.7;
}
#kbc-strategic-credit-page-v3 .kbc-hero-proof{
  display:flex;
  flex-wrap:wrap;
  gap:10px;
  margin-top:25px;
}
#kbc-strategic-credit-page-v3 .kbc-hero-proof span{
  display:inline-flex;
  min-height:36px;
  align-items:center;
  padding:7px 12px;
  border:1px solid rgba(255,255,255,.14);
  border-radius:999px;
  color:rgba(255,255,255,.87);
  background:rgba(255,255,255,.05);
  font-size:12px;
  font-weight:700;
}
#kbc-strategic-credit-page-v3 .kbc-hero-visual{
  padding:24px;
  border:1px solid rgba(255,255,255,.14);
  border-radius:22px;
  background:rgba(255,255,255,.055);
  box-shadow:0 28px 65px rgba(0,0,0,.23);
  backdrop-filter:blur(12px);
}
#kbc-strategic-credit-page-v3 .kbc-hero-visual-header{
  display:flex;
  justify-content:space-between;
  gap:16px;
  margin-bottom:22px;
}
#kbc-strategic-credit-page-v3 .kbc-hero-visual-header span{
  color:var(--kbc-gold);
  font-size:11px;
  font-weight:800;
  letter-spacing:.1em;
  text-transform:uppercase;
}
#kbc-strategic-credit-page-v3 .kbc-hero-visual-header strong{
  color:var(--kbc-white);
  font-size:1rem;
}
#kbc-strategic-credit-page-v3 .kbc-hero-path{display:grid;gap:10px}
#kbc-strategic-credit-page-v3 .kbc-hero-path-step{
  position:relative;
  display:grid;
  grid-template-columns:56px minmax(0,1fr) auto;
  gap:14px;
  align-items:center;
  min-height:70px;
  padding:12px 14px;
  border:1px solid rgba(255,255,255,.12);
  border-radius:14px;
  background:rgba(32,20,50,.5);
}
#kbc-strategic-credit-page-v3 .kbc-hero-path-credit{
  display:grid;
  width:46px;height:46px;
  place-items:center;
  border-radius:13px;
  color:var(--kbc-dark);
  background:var(--kbc-gold);
  font-size:13px;
  font-weight:800;
}
#kbc-strategic-credit-page-v3 .kbc-hero-path-copy strong{
  display:block;color:var(--kbc-white);font-size:13px;line-height:1.35;
}
#kbc-strategic-credit-page-v3 .kbc-hero-path-copy span{
  display:block;margin-top:3px;color:rgba(255,255,255,.62);font-size:11px;
}
#kbc-strategic-credit-page-v3 .kbc-hero-path-time{
  color:rgba(255,255,255,.7);white-space:nowrap;font-size:10px;font-weight:800;text-transform:uppercase;
}
#kbc-strategic-credit-page-v3 .kbc-hero-metrics{
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  border-top:1px solid rgba(255,255,255,.13);
  background:rgba(0,0,0,.08);
}
#kbc-strategic-credit-page-v3 .kbc-hero-metric{
  min-height:142px;
  padding:25px;
  border-right:1px solid rgba(255,255,255,.1);
}
#kbc-strategic-credit-page-v3 .kbc-hero-metric:last-child{border-right:0}
#kbc-strategic-credit-page-v3 .kbc-hero-metric strong{
  display:block;
  margin-bottom:9px;
  color:var(--kbc-gold);
  font-size:clamp(2rem,4vw,2.8rem);
  font-weight:800;
  line-height:1;
}
#kbc-strategic-credit-page-v3 .kbc-hero-metric span{
  display:block;color:rgba(255,255,255,.7);font-size:12px;line-height:1.45;
}

#kbc-strategic-credit-page-v3 .kbc-nav-sentinel{
  width:100%;
  height:1px;
  margin:0;
  padding:0;
  pointer-events:none;
}
#kbc-strategic-credit-page-v3 .kbc-page-nav{
  position:sticky;
  z-index:1000;
  top:var(--kbc-total-sticky-offset);
  display:block !important;
  width:100% !important;
  height:auto !important;
  min-height:var(--kbc-page-nav-height) !important;
  max-height:72px !important;
  margin:0 !important;
  padding:0 !important;
  overflow:hidden !important;
  transform:none !important;
  border-top:1px solid rgba(87,58,125,.08);
  border-bottom:1px solid rgba(87,58,125,.14);
  background:#ffffff;
  color:var(--kbc-dark);
  box-shadow:0 8px 24px rgba(32,20,50,.07);
  transition:background-color .22s ease,color .22s ease,border-color .22s ease,box-shadow .22s ease;
}
#kbc-strategic-credit-page-v3 .kbc-page-nav > .kbc-container{
  display:block !important;
  height:auto !important;
  min-height:0 !important;
  max-height:72px !important;
  margin-inline:auto !important;
  padding-top:0 !important;
  padding-bottom:0 !important;
}
#kbc-strategic-credit-page-v3 .kbc-page-nav.is-stuck{
  border-top-color:rgba(255,255,255,.05);
  border-bottom-color:rgba(255,255,255,.10);
  background:#17131f;
  color:#ffffff;
  box-shadow:0 12px 30px rgba(32,20,50,.22);
}
#kbc-strategic-credit-page-v3 .kbc-page-nav-scroll{
  display:flex !important;
  width:100% !important;
  height:var(--kbc-page-nav-height) !important;
  min-height:var(--kbc-page-nav-height) !important;
  max-height:64px !important;
  align-items:center !important;
  justify-content:center;
  gap:6px;
  margin:0 !important;
  padding:0 !important;
  overflow-x:auto !important;
  overflow-y:hidden !important;
  white-space:nowrap;
  scrollbar-width:none;
  -webkit-overflow-scrolling:touch;
  overscroll-behavior-inline:contain;
}
#kbc-strategic-credit-page-v3 .kbc-page-nav-scroll::-webkit-scrollbar{display:none}
#kbc-strategic-credit-page-v3 .kbc-page-nav a{
  position:relative;
  display:inline-flex;
  min-height:42px;
  flex:0 0 auto;
  align-items:center;
  justify-content:center;
  padding:9px 14px;
  border:1px solid transparent;
  border-radius:9px;
  color:var(--kbc-dark);
  background:transparent;
  text-decoration:none;
  white-space:nowrap;
  font-size:12px;
  font-weight:750;
  line-height:1.2;
  transition:color .18s ease,background-color .18s ease,border-color .18s ease;
}
#kbc-strategic-credit-page-v3 .kbc-page-nav a:hover{
  color:var(--kbc-purple);
  background:var(--kbc-light-purple);
}
#kbc-strategic-credit-page-v3 .kbc-page-nav a.is-active{
  color:var(--kbc-purple);
  border-color:rgba(92,37,156,.18);
  background:var(--kbc-light-purple);
}
#kbc-strategic-credit-page-v3 .kbc-page-nav.is-stuck a{
  color:#ffffff;
}
#kbc-strategic-credit-page-v3 .kbc-page-nav.is-stuck a:hover{
  color:#ffffff;
  background:rgba(255,255,255,.08);
}
#kbc-strategic-credit-page-v3 .kbc-page-nav.is-stuck a.is-active{
  color:#ffffff;
  border-color:rgba(229,189,89,.28);
  background:rgba(255,255,255,.12);
}
#kbc-strategic-credit-page-v3 .kbc-page-nav a.is-active::after{
  position:absolute;
  right:11px;
  bottom:4px;
  left:11px;
  height:2px;
  border-radius:999px;
  background:var(--kbc-gold);
  content:"";
}

#kbc-strategic-credit-page-v3 .kbc-overview-layout{
  display:grid;
  grid-template-columns:minmax(0,.72fr) minmax(0,1.28fr);
  gap:34px;
  align-items:start;
}
#kbc-strategic-credit-page-v3 .kbc-overview-summary{
  position:sticky;
  top:calc(var(--kbc-total-sticky-offset) + var(--kbc-page-nav-height) + 24px);
}
#kbc-strategic-credit-page-v3 .kbc-overview-score{
  display:grid;
  min-height:290px;
  place-items:center;
  padding:30px;
  border-radius:24px;
  color:#fff;
  background:
    radial-gradient(circle at 90% 10%,rgba(117,64,220,.62),transparent 40%),
    linear-gradient(145deg,var(--kbc-dark),var(--kbc-medium));
  box-shadow:var(--kbc-shadow-raised);
  text-align:center;
}
#kbc-strategic-credit-page-v3 .kbc-overview-score strong{
  display:block;color:var(--kbc-gold);font-size:clamp(4rem,9vw,7rem);font-weight:800;line-height:.85;
}
#kbc-strategic-credit-page-v3 .kbc-overview-score span{
  display:block;margin-top:18px;color:rgba(255,255,255,.77);font-size:12px;font-weight:800;letter-spacing:.13em;text-transform:uppercase;
}
#kbc-strategic-credit-page-v3 .kbc-overview-list{display:grid;gap:15px}
#kbc-strategic-credit-page-v3 .kbc-overview-item{
  display:grid;
  grid-template-columns:74px minmax(0,1fr) auto;
  gap:18px;
  align-items:center;
  min-height:118px;
  padding:21px;
  border:1px solid var(--kbc-border);
  border-radius:18px;
  background:#fff;
  box-shadow:var(--kbc-shadow);
}
#kbc-strategic-credit-page-v3 .kbc-overview-item-number{
