    font-size:12px;
  }
}

(function(){
  "use strict";

  var root=document.getElementById("kbc-strategic-credit-page-v3");
  if(!root||root.dataset.kbcStickyReady==="true"){return}
  root.dataset.kbcStickyReady="true";
  root.classList.add("is-js");

  var nav=root.querySelector(".kbc-page-nav");
  var navScroll=root.querySelector(".kbc-page-nav-scroll");
  var sentinel=root.querySelector(".kbc-nav-sentinel");
  if(!nav||!navScroll){return}

  var reduceMotion=window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var headerSelectors=[
    "header","#masthead",".site-header",".main-header",".header",
    ".elementor-location-header",'[data-elementor-type="header"]',
    "header.elementor",".elementor-sticky",".elementor-sticky--active",
    ".ast-primary-header-bar",".ast-builder-grid-row-container",
    ".et-l--header",".fusion-header-wrapper",".fusion-header",
    ".site-header-section",".header-wrapper",".main-navigation",
    ".wp-site-blocks > header",".wp-block-template-part > header"
  ];

  var navigationLinks=Array.prototype.slice.call(nav.querySelectorAll('a[href^="#"]'));
  var sections=navigationLinks.map(function(link){
    var selector=link.getAttribute("href");
    return selector&&selector!=="#"?root.querySelector(selector):null;
  }).filter(Boolean);

  var activeObserver=null;
  var stickyObserver=null;
  var resizeObserver=null;
  var mutationObserver=null;
  var scheduled=false;
  var lastTotalOffset=0;
  var lastNavHeight=0;

  function isVisible(element){
    if(!element||root.contains(element)){return false}
    var style=window.getComputedStyle(element);
    if(style.display==="none"||style.visibility==="hidden"||parseFloat(style.opacity)===0){return false}
    var rect=element.getBoundingClientRect();
    if(rect.width<120||rect.height<18){return false}
    if(rect.bottom<=0){return false}
    return true;
  }

  function getAdminBarHeight(){
    var admin=document.getElementById("wpadminbar");
    if(!admin){return 0}
    var style=window.getComputedStyle(admin);
    if(style.display==="none"||style.visibility==="hidden"||parseFloat(style.opacity)===0){return 0}
    var rect=admin.getBoundingClientRect();
    return rect.height>0?Math.round(rect.height):0;
  }

  function collectHeaderCandidates(){
    var set=new Set();
    headerSelectors.forEach(function(selector){
      try{
        document.querySelectorAll(selector).forEach(function(element){
          if(element!==nav&&!root.contains(element)){set.add(element)}
        });
      }catch(error){}
    });
    return Array.from(set);
  }

  function measureHeaderOffset(){
    var adminHeight=getAdminBarHeight();
    var candidates=collectHeaderCandidates();
    var topLimit=Math.min(Math.max(window.innerHeight*.32,220),360);
    var maximumBottom=0;

    candidates.forEach(function(element){
      if(!isVisible(element)){return}
      var rect=element.getBoundingClientRect();
      var style=window.getComputedStyle(element);
      var positioned=style.position==="fixed"||style.position==="sticky";
      var intersectsTop=rect.top<=adminHeight+12&&rect.bottom>adminHeight;
      var nearTop=rect.top<topLimit&&rect.bottom>adminHeight;

      if(positioned||intersectsTop||nearTop){
        maximumBottom=Math.max(maximumBottom,rect.bottom);
      }
    });

    var fallback=window.innerWidth<=680?70:82;
    var totalOffset;

    if(maximumBottom>adminHeight+8){
      totalOffset=maximumBottom;
    }else{
      totalOffset=adminHeight+fallback;
    }

    totalOffset=Math.max(adminHeight,totalOffset);
    totalOffset=Math.min(totalOffset,adminHeight+220);

    var siteHeaderHeight=Math.max(0,totalOffset-adminHeight);

    root.style.setProperty("--kbc-admin-bar-height",adminHeight+"px");
    root.style.setProperty("--kbc-site-header-height",siteHeaderHeight+"px");
    root.style.setProperty("--kbc-total-sticky-offset",Math.round(totalOffset)+"px");

    return Math.round(totalOffset);
  }

  function measureNavigation(){
    /*
      Never feed an externally stretched nav height back into the CSS variable.
      Some WordPress themes apply global rules to navigation elements; reading an
      accidental 100vh height here previously created a self-reinforcing loop.
    */
    var fallback=window.innerWidth<=680?54:58;
    var measured=Math.round(navScroll.scrollHeight||fallback);
    var height=measured>=44&&measured<=64?measured:fallback;
    height=Math.max(48,Math.min(64,height));
    root.style.setProperty("--kbc-page-nav-height",height+"px");
    return height;
  }

  function keepActiveLinkVisible(link){
    if(!link){return}
    var containerRect=navScroll.getBoundingClientRect();
    var linkRect=link.getBoundingClientRect();
    if(linkRect.left<containerRect.left+8||linkRect.right>containerRect.right-8){
      link.scrollIntoView({
        behavior:reduceMotion?"auto":"smooth",
        block:"nearest",
        inline:"center"
      });
    }
  }

  function setActiveNavigation(sectionId){
    navigationLinks.forEach(function(link){
      var active=link.getAttribute("href")==="#"+sectionId;
      link.classList.toggle("is-active",active);
      if(active){
        link.setAttribute("aria-current","location");
        keepActiveLinkVisible(link);
      }else{
        link.removeAttribute("aria-current");
      }
    });
  }

  function setupActiveObserver(totalOffset,navHeight){
    if(activeObserver){activeObserver.disconnect()}
    var readableTop=Math.round(totalOffset+navHeight+18);
    var states=new Map();

    activeObserver=new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        states.set(entry.target,{
          intersecting:entry.isIntersecting,
          ratio:entry.intersectionRatio,
          top:entry.boundingClientRect.top
        });
      });

      var best=null;
      sections.forEach(function(section,index){
        var state=states.get(section);
        if(!state||!state.intersecting){return}
        var distance=Math.abs(state.top-readableTop);
        var score=distance-(state.ratio*120)+(index*.001);
        if(!best||score<best.score){best={id:section.id,score:score}}
      });

      if(best){setActiveNavigation(best.id)}
    },{
      root:null,
      rootMargin:"-"+readableTop+"px 0px -58% 0px",
      threshold:[0,.01,.08,.2,.4,.65]
    });

    sections.forEach(function(section){activeObserver.observe(section)});
  }

  function setupStickyObserver(totalOffset){
    if(!sentinel){return}
    if(stickyObserver){stickyObserver.disconnect()}
    stickyObserver=new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        var stuck=!entry.isIntersecting&&entry.boundingClientRect.top<totalOffset+1;
        nav.classList.toggle("is-stuck",stuck);
      });
    },{
      root:null,
      rootMargin:"-"+Math.round(totalOffset)+"px 0px 0px 0px",
      threshold:[0,1]
    });
    stickyObserver.observe(sentinel);
  }

  function updateMeasurements(){
    scheduled=false;
    var totalOffset=measureHeaderOffset();
    var navHeight=measureNavigation();

    if(totalOffset!==lastTotalOffset||navHeight!==lastNavHeight){
      lastTotalOffset=totalOffset;
      lastNavHeight=navHeight;
      setupStickyObserver(totalOffset);
      setupActiveObserver(totalOffset,navHeight);
    }
  }

  function scheduleMeasurements(){
    if(scheduled){return}
    scheduled=true;
    window.requestAnimationFrame(updateMeasurements);
  }

  function scrollToTarget(target){
    var totalOffset=parseFloat(getComputedStyle(root).getPropertyValue("--kbc-total-sticky-offset"))||lastTotalOffset||82;
    var navHeight=parseFloat(getComputedStyle(root).getPropertyValue("--kbc-page-nav-height"))||lastNavHeight||58;
    var targetY=target.getBoundingClientRect().top+window.pageYOffset-totalOffset-navHeight-18;
    window.scrollTo({
      top:Math.max(0,targetY),
      behavior:reduceMotion?"auto":"smooth"
    });
  }

  Array.prototype.slice.call(root.querySelectorAll('a[href^="#"]')).forEach(function(link){
    link.addEventListener("click",function(event){
      var selector=link.getAttribute("href");
      if(!selector||selector==="#"){return}
      var target=root.querySelector(selector);
      if(!target){return}
      event.preventDefault();
      scrollToTarget(target);
      if(window.history&&window.history.pushState){
        window.history.pushState(null,"",selector);
      }else{
        window.location.hash=selector;
      }
    });
  });

  Array.prototype.slice.call(root.querySelectorAll("[data-kbc-details-target]")).forEach(function(button){
    button.addEventListener("click",function(){
      var id=button.getAttribute("data-kbc-details-target");
      var panel=id?root.querySelector("#"+id):null;
      if(!panel){return}
      panel.open=true;
      window.setTimeout(function(){scrollToTarget(panel)},40);
    });
  });

  var revealItems=Array.prototype.slice.call(root.querySelectorAll(".kbc-reveal"));
  if(reduceMotion||!("IntersectionObserver" in window)){
    revealItems.forEach(function(item){item.classList.add("is-visible")});
  }else{
    var revealObserver=new IntersectionObserver(function(entries,observer){
      entries.forEach(function(entry){
        if(entry.isIntersecting){
          entry.target.classList.add("is-visible");
          observer.unobserve(entry.target);
        }
      });
    },{rootMargin:"0px 0px -8% 0px",threshold:.08});
    revealItems.forEach(function(item){revealObserver.observe(item)});
  }

  var essentialPanels=Array.prototype.slice.call(root.querySelectorAll(".kbc-essential"));
  essentialPanels.forEach(function(panel){
    panel.addEventListener("toggle",function(){
      if(!panel.open){return}
      essentialPanels.forEach(function(other){
        if(other!==panel){other.removeAttribute("open")}
      });
      scheduleMeasurements();
    });
  });

  if("ResizeObserver" in window){
    resizeObserver=new ResizeObserver(scheduleMeasurements);
    resizeObserver.observe(nav);
    var admin=document.getElementById("wpadminbar");
    if(admin){resizeObserver.observe(admin)}
    collectHeaderCandidates().forEach(function(element){
      try{resizeObserver.observe(element)}catch(error){}
    });
  }

  if("MutationObserver" in window&&document.body){
    mutationObserver=new MutationObserver(function(mutations){
      var changedOutsidePage=mutations.some(function(mutation){
        return !root.contains(mutation.target);
      });
      if(changedOutsidePage){scheduleMeasurements()}
    });
    mutationObserver.observe(document.body,{
      subtree:true,
      childList:true,
      attributes:true,
      attributeFilter:["class","style"]
    });
  }

  window.addEventListener("resize",scheduleMeasurements,{passive:true});
  window.addEventListener("orientationchange",scheduleMeasurements,{passive:true});
  window.addEventListener("scroll",scheduleMeasurements,{passive:true});
  window.addEventListener("load",scheduleMeasurements,{once:true});

  if(document.fonts&&document.fonts.ready){
    document.fonts.ready.then(scheduleMeasurements).catch(function(){});
  }

  scheduleMeasurements();
  window.setTimeout(scheduleMeasurements,150);
  window.setTimeout(scheduleMeasurements,500);
  window.setTimeout(scheduleMeasurements,1200);
})();
